parameters.text:
=Analyze the following learning material and create a structured summary.

Content: {{ $json.content }}

Provide your response in the following JSON format:
{
  "title": "Extracted or inferred title",
  "summary": "Brief overview in 2-3 sentences",
  "keyPoints": ["Point 1", "Point 2", "Point 3", "Point 4", "Point 5"],
  "mainConcepts": ["Concept 1", "Concept 2", "Concept 3"],
  "difficulty": "beginner|intermediate|advanced"
}

parameters.jsCode:
const teacherOutput = $input.first().json.output;
const contentData = $("refContent").first().json;

let parsed;
try {
  parsed = JSON.parse(teacherOutput);
} catch (e) {
  const jsonMatch = teacherOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error("Could not parse teacher output");
  }
}

const materialId = "LM-" + Date.now();

return [{
  json: {
    materialId: materialId,
    url: contentData.url,
    userId: contentData.userId,
    title: parsed.title,
    content: contentData.content,
    summary: parsed.summary,
    keyPoints: parsed.keyPoints,
    keyPointsString: parsed.keyPoints.join('; '),
    mainConcepts: parsed.mainConcepts,
    mainConceptsString: parsed.mainConcepts.join('; '),
    difficulty: parsed.difficulty,
    addedDate: new Date().toISOString()
  }
}];

