parameters.jsCode:
const examinerOutput = $input.first().json.output;
const materialId = $("refMaterial").item.json.materialId;
const userId = $("refMaterial").item.json.userId;
const queryId = $("refMaterial").item.json.queryId;

let parsed;
try {
  parsed = JSON.parse(examinerOutput);
} catch (e) {
  const jsonMatch = examinerOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error("Could not parse examiner output");
  }
}

const quizId = "QUIZ-" + Date.now();

return [{
  json: {
    quizId: quizId,
    materialId: materialId,
    userId: userId,
    queryId: queryId,
    questions: parsed.questions,
    questionsString: JSON.stringify(parsed.questions),
    currentQuestionIndex: 0,
    userAnswers: [],
    userAnswersString: JSON.stringify([])
  }
}];

const quiz = $input.first().json;
const answer = $('refAnswer').first().json;

const questions = JSON.parse(quiz.questionsString);
const userAnswers = JSON.parse(quiz.userAnswersString);

const currentQuestion = questions[answer.questionIndex];
const isCorrect = currentQuestion.correctAnswer === answer.userAnswer;

userAnswers[answer.questionIndex] = {
  questionIndex: answer.questionIndex,
  userAnswer: answer.userAnswer,
  correctAnswer: currentQuestion.correctAnswer,
  isCorrect: isCorrect,
  explanation: currentQuestion.explanation
};

const nextIndex = answer.questionIndex + 1;
const isLastQuestion = nextIndex >= questions.length;

return [{
  json: {
    quizId: quiz.quizId,
    chatId: answer.chatId,
    queryId: answer.queryId,
    userAnswers: userAnswers,
    userAnswersString: JSON.stringify(userAnswers),
    currentQuestionIndex: nextIndex,
    isLastQuestion: isLastQuestion
  }
}];

const quizStatus = $('refQuizStatus').first().json;
const userAnswers = quizStatus.userAnswers;

const correctCount = userAnswers.filter(a => a.isCorrect).length;
const totalQuestions = userAnswers.length;
const percentage = Math.round((correctCount / totalQuestions) * 100);

let feedback = "";
for (let i = 0; i < userAnswers.length; i++) {
  const answer = userAnswers[i];
  const emoji = answer.isCorrect ? "✅" : "❌";
  const header = emoji + " Question " + (i + 1);
  const correctAnswerStatus = `${header}: ${answer.userAnswer} is correct.\n\n`;
  const failedAnswerStatus = `${header}: ${answer.userAnswer} is wrong, it should be ${answer.correctAnswer}. ${answer.explanation}\n\n`

  feedback += answer.isCorrect ? correctAnswerStatus : failedAnswerStatus;
}

return [{
  json: {
    chatId: quizStatus.chatId,
    queryId: quizStatus.queryId,
    correctCount: correctCount,
    totalQuestions: totalQuestions,
    percentage: percentage,
    feedback: feedback
  }
}];

const html = $input.first().json.rawHtml;
const inputData = $('refInput').first().json;

let cleaned = html
  .replace(/<script[^>]*>([\s\S]*?)<\/script>/gi, "")
  .replace(/<style[^>]*>([\s\S]*?)<\/style>/gi, "")
  .replace(/<head[^>]*>([\s\S]*?)<\/head>/gi, "")
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;/g, " ")
  .replace(/&amp;/g, "&")
  .replace(/&lt;/g, "<")
  .replace(/&gt;/g, ">")
  .replace(/&quot;/g, '"')  
  .replace(/&#39;/g, "'")
  .replace(/\s+/g, " ")
  .trim();

return [{
  json: {
    url: inputData.url,
    userId: inputData.userId,
    content: cleaned
  }
}];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  const {questionsString, userAnswersString, currentQuestionIndex} = item.json;
  item.json.questions = JSON.parse(questionsString);
  item.json.userAnswers = JSON.parse(userAnswersString);
  item.json.currentQustion = item.json.questions[currentQuestionIndex];
}

return $input.all();

const callbackData = $input.first().json.callback_query.data;
const parts = callbackData.replace("answer_", "").split("_");

return [{
  json: {
    quizId: parts[0],
    questionIndex: parseInt(parts[1]),
    userAnswer: parts[2],
    chatId: $input.first().json.callback_query.message.chat.id,
    queryId: $input.first().json.callback_query.id
  }
}];
